//! The AArch64 target intrinsics (WP-083, `spec/codegen.md` §5.5.1 "NEON
//! intrinsics (WP-083)").
//!
//! `data/neon/cases.txt` (generated by `data/neon/cases.py` from the
//! declarations clang 22 and 19 emit for `<arm_neon.h>` and those of the
//! corpus) has one call per signature of each lowered intrinsic and per
//! immediate; [`module`] makes each a function that loads the operands
//! from bytes derived from its six arguments, calls the intrinsic and
//! hashes what it produced. Every
//! function is compiled by hod (plain, every stress option, far mode)
//! and by `llc -O0 -global-isel=0 -fast-isel=0` of LLVM 22 and 19, linked
//! with a C driver under every linker present and run with random
//! arguments; every build must print what the first `llc` build prints.
//! The host runs every extension the cases use (`/proc/cpuinfo`: `aes`,
//! `pmull`, `sha1`, `sha2`, `sha3`, `sha512`, `asimdrdm`, `asimddp`,
//! `i8mm`, `fphp`, `asimdhp`, `asimdfhm`, `fcma`, `frint`).

mod common;

use std::fmt::Write as _;

use common::linking::Toolchain;
use common::{assert_refused, compile_ll, ll_header, parse, write_object};
use hod_a64::compile_module;
use hod_cg::{Options, RelocModel, Stress};

const CALLS: &str = include_str!("data/neon/cases.txt");

/// The calls whose results `llc` 22 computes differently from `llc` 19:
/// the 16-bit sum of `saddlv` of bytes, which 19 sign-extends to `i32`
/// and 22 zero-extends (hod sign-extends since WP-101, the signed sum;
/// `<arm_neon.h>` truncates it).
const LLVM22_DIFFERS: &[&str] =
    &["@llvm.aarch64.neon.saddlv.i32.v8i8(", "@llvm.aarch64.neon.saddlv.i32.v16i8("];

/// What every case uses: `@fill` writes 32 words derived from the six
/// arguments, `@hash` hashes 64 words.
const SUPPORT: &str = r#"
declare void @llvm.memset.p0.i64(ptr, i8, i64, i1)
declare i64 @llvm.fshl.i64(i64, i64, i64)

define internal void @fill(ptr %in, i64 %a0, i64 %a1, i64 %a2, i64 %a3, i64 %a4, i64 %a5) {
entry:
  %args = alloca [6 x i64]
  store i64 %a0, ptr %args
  %g1 = getelementptr i64, ptr %args, i64 1
  store i64 %a1, ptr %g1
  %g2 = getelementptr i64, ptr %args, i64 2
  store i64 %a2, ptr %g2
  %g3 = getelementptr i64, ptr %args, i64 3
  store i64 %a3, ptr %g3
  %g4 = getelementptr i64, ptr %args, i64 4
  store i64 %a4, ptr %g4
  %g5 = getelementptr i64, ptr %args, i64 5
  store i64 %a5, ptr %g5
  br label %loop
loop:
  %j = phi i64 [ 0, %entry ], [ %next, %loop ]
  %k = urem i64 %j, 6
  %pa = getelementptr i64, ptr %args, i64 %k
  %a = load i64, ptr %pa
  %j1 = add i64 %j, 1
  %c = mul i64 %j1, -7046029254386353131
  %odd = or i64 %c, 1
  %m = mul i64 %a, %odd
  %by = mul i64 %j, 7
  %r = call i64 @llvm.fshl.i64(i64 %m, i64 %m, i64 %by)
  %p = getelementptr i64, ptr %in, i64 %j
  store i64 %r, ptr %p
  %next = add i64 %j, 1
  %done = icmp eq i64 %next, 32
  br i1 %done, label %exit, label %loop
exit:
  ret void
}

define internal i64 @hash(ptr %p) {
entry:
  br label %loop
loop:
  %i = phi i64 [ 0, %entry ], [ %n, %loop ]
  %h = phi i64 [ 0, %entry ], [ %h2, %loop ]
  %q = getelementptr i64, ptr %p, i64 %i
  %w = load i64, ptr %q
  %rot = call i64 @llvm.fshl.i64(i64 %h, i64 %h, i64 13)
  %x = xor i64 %rot, %w
  %h2 = mul i64 %x, -7046029254386353131
  %n = add i64 %i, 1
  %done = icmp eq i64 %n, 64
  br i1 %done, label %exit, label %loop
exit:
  ret i64 %h2
}

attributes #0 = { "target-features"="+neon,+fullfp16,+rdm,+dotprod,+i8mm,+aes,+sha2,+sha3,+complxnum,+fp16fml,+v8.5a" }
"#;

/// The parts of `text` between commas outside brackets.
fn split_top(text: &str) -> Vec<&str> {
    let (mut out, mut depth, mut start) = (Vec::new(), 0i32, 0);
    for (i, ch) in text.char_indices() {
        match ch {
            '<' | '{' | '(' => depth += 1,
            '>' | '}' | ')' => depth -= 1,
            ',' if depth == 0 => {
                out.push(text[start..i].trim());
                start = i + 1;
            }
            _ => {}
        }
    }
    if !text[start..].trim().is_empty() {
        out.push(text[start..].trim());
    }
    out
}

/// The calls of `cases.txt`, in order.
fn calls() -> Vec<&'static str> {
    CALLS.lines().filter(|l| !l.starts_with('#') && !l.trim().is_empty()).collect()
}

/// The function `@c<k>` of `call` (`<ret> @<name>(<args>)`), and its
/// declaration.
fn case(k: usize, call: &str) -> (String, String) {
    let (ret, callee) = call.split_once(" @").expect("a call");
    let (name, args) = callee.split_once('(').expect("arguments");
    let args = split_top(args.strip_suffix(')').expect("arguments"));
    let mut body = format!(
        "define i64 @c{k}(i64 %a0, i64 %a1, i64 %a2, i64 %a3, i64 %a4, i64 %a5) #0 {{\n  \
         %in = alloca [32 x i64], align 16\n  %out = alloca [64 x i64], align 16\n  \
         call void @llvm.memset.p0.i64(ptr %out, i8 0, i64 512, i1 false)\n  \
         call void @fill(ptr %in, i64 %a0, i64 %a1, i64 %a2, i64 %a3, i64 %a4, i64 %a5)\n"
    );
    let (mut types, mut values) = (Vec::new(), Vec::new());
    let mut offset = 0;
    for (i, arg) in args.iter().enumerate() {
        if let Some(ty) = arg.strip_suffix(" %") {
            writeln!(body, "  %q{i} = getelementptr i8, ptr %in, i64 {offset}").unwrap();
            writeln!(body, "  %x{i} = load {ty}, ptr %q{i}, align 1").unwrap();
            values.push(format!("{ty} %x{i}"));
            types.push(ty);
            offset = (offset + 16) % 192;
        } else {
            let ty = match arg.find(" splat") {
                Some(at) => &arg[..at],
                None => arg.rsplit_once(' ').expect("a typed value").0,
            };
            values.push((*arg).to_owned());
            types.push(ty);
        }
    }
    let call = format!("@{name}({})", values.join(", "));
    if ret == "void" {
        writeln!(body, "  call void {call}").unwrap();
    } else {
        writeln!(body, "  %res = call {ret} {call}\n  store {ret} %res, ptr %out, align 1")
            .unwrap();
    }
    body += "  %h = call i64 @hash(ptr %out)\n  ret i64 %h\n}\n";
    (body, format!("declare {ret} @{name}({})\n", types.join(", ")))
}

/// The module of every case (`None`) or of case `only`, without the
/// header.
fn module(only: Option<usize>) -> String {
    let mut text = String::from(SUPPORT);
    let mut declared = std::collections::HashSet::new();
    for (k, call) in calls().into_iter().enumerate() {
        if only.is_some_and(|o| o != k) {
            continue;
        }
        let (body, declaration) = case(k, call);
        if declared.insert(declaration.clone()) {
            text += &declaration;
        }
        text += &body;
    }
    text
}

const DEFAULT: Options = Options {
    reloc_model: RelocModel::Static,
    code_model: None,
    function_sections: false,
    data_sections: false,
    stress: Stress { min_pool: false, far: false, displace: false },
    debug_compression: hod_obj::Compression::None,
};

const MODES: [(&str, Options); 3] = [
    ("plain", DEFAULT),
    ("stress", Options { stress: Stress::ALL, ..DEFAULT }),
    ("far", Options { stress: Stress { min_pool: false, far: true, displace: false }, ..DEFAULT }),
];

/// xorshift64*: a fixed sequence, so that every run checks the same calls.
struct Rng(u64);

impl Rng {
    fn next(&mut self) -> u64 {
        self.0 ^= self.0 >> 12;
        self.0 ^= self.0 << 25;
        self.0 ^= self.0 >> 27;
        self.0.wrapping_mul(0x2545_f491_4f6c_dd1d)
    }

    /// An edge value or a random word.
    fn word(&mut self) -> u64 {
        const EDGES: [u64; 6] = [0, 1, u64::MAX, 1 << 63, (1 << 63) - 1, 0x7f7f_8080_7fff_8000];
        let r = self.next();
        if r.is_multiple_of(4) { EDGES[(r >> 8) as usize % EDGES.len()] } else { self.next() }
    }
}

/// Every case compiles in every mode (each by itself, so that a failure
/// names all the cases that fail).
#[test]
fn every_case_compiles() {
    let mut failed = Vec::new();
    for (k, what) in calls().into_iter().enumerate() {
        let (module, bodies) = parse(&format!("{}{}", ll_header(22), module(Some(k))));
        for (mode, options) in &MODES {
            if let Err(e) = compile_module(&module, &bodies, options) {
                failed.push(format!("c{k} ({what}) {mode}: {e}"));
            }
        }
    }
    assert!(failed.is_empty(), "{} failures:\n{}", failed.len(), failed.join("\n"));
}

/// Runs every case with `per` random argument lists under hod and `llc`
/// of each LLVM major present.
#[test]
fn cases_match_llc() {
    let names: Vec<(String, &str)> =
        calls().into_iter().enumerate().map(|(k, call)| (format!("c{k}"), call)).collect();
    let all = module(None);
    let mut rng = Rng(0x0830_0083);
    let per = 3;
    let mut c = String::from(
        "#include <stdio.h>\n#include <stdint.h>\n\
         typedef uint64_t (*fn6)(uint64_t, uint64_t, uint64_t, uint64_t, uint64_t, uint64_t);\n",
    );
    for (name, _) in &names {
        writeln!(c, "uint64_t {name}(void);").unwrap();
    }
    c.push_str("static const struct { fn6 f; uint64_t a[6]; } calls[] = {\n");
    let mut calls = Vec::new();
    for (name, what) in &names {
        for _ in 0..per {
            let args = [(); 6].map(|()| rng.word());
            let list: Vec<String> = args.iter().map(|a| format!("{a}ULL")).collect();
            writeln!(c, "  {{ (fn6){name}, {{ {} }} }},", list.join(", ")).unwrap();
            calls.push((name.as_str(), *what, args));
        }
    }
    c.push_str(
        "};\nint main(void) {\n  for (unsigned i = 0; i < sizeof calls / sizeof calls[0]; i++) {\n    \
         const uint64_t *a = calls[i].a;\n    \
         printf(\"%llu\\n\", (unsigned long long)calls[i].f(a[0], a[1], a[2], a[3], a[4], a[5]));\n    \
         fflush(stdout);\n  \
         }\n  return 0;\n}\n",
    );
    let dir = hod_testutil::Scratch::new("a64-neon-cases");
    let Some(toolchain) = Toolchain::host(&dir) else { return };
    let driver = toolchain.compile_c(&dir, "driver", &c, &[]);
    let mut objects = Vec::new();
    // 19 first: the reference is the first build (`LLVM22_DIFFERS`).
    for major in [19, 22] {
        let Some(llc) = hod_testutil::tool(&format!("llc-{major}")) else { continue };
        let input = dir.write(&format!("llc{major}.ll"), format!("{}{all}", ll_header(major)));
        let output = dir.join(format!("llc{major}.o"));
        let mut command = std::process::Command::new(llc);
        command
            .args(["-O0", "-global-isel=0", "-fast-isel=0", "-filetype=obj"])
            .arg(&input)
            .arg("-o")
            .arg(&output);
        let outcome = hod_testutil::run_with(&mut command, &[], std::time::Duration::from_mins(5));
        assert!(outcome.success(), "llc-{major}: {}", outcome.stderr_text());
        objects.push((format!("llc-{major}"), output));
    }
    if objects.is_empty() {
        return;
    }
    let (module, bodies) = parse(&format!("{}{all}", ll_header(22)));
    for (name, options) in &MODES {
        let emitted =
            compile_module(&module, &bodies, options).unwrap_or_else(|e| panic!("{name}: {e}"));
        objects.push(((*name).to_owned(), write_object(&dir, &format!("{name}.o"), &emitted)));
    }
    let mut reference: Option<String> = None;
    for linker in &toolchain.linkers {
        for (name, object) in &objects {
            let exe = dir.join(format!("{name}-{}", linker.name));
            let ran = toolchain.link_and_run(linker, &[], &[&driver, object], &exe);
            let got = ran.stdout_text();
            if !ran.success() {
                let (f, what, args) = calls[got.lines().count().min(calls.len() - 1)];
                panic!(
                    "{name} under {}: @{f} ({what}) {args:x?}: {}",
                    linker.name,
                    ran.stderr_text()
                );
            }
            let reference = reference.get_or_insert_with(|| got.clone());
            let wrong: Vec<String> = got
                .lines()
                .zip(reference.lines())
                .zip(&calls)
                .filter(|((g, w), (_, what, _))| {
                    g != w && !(name == "llc-22" && LLVM22_DIFFERS.iter().any(|d| what.contains(d)))
                })
                .map(|((g, w), (f, what, args))| format!("@{f} ({what}) {args:x?}: {g}, want {w}"))
                .collect();
            assert!(
                wrong.is_empty() && got.lines().count() == calls.len(),
                "{name} under {}: {} calls differ:\n{}",
                linker.name,
                wrong.len(),
                wrong.join("\n")
            );
        }
    }
    eprintln!(
        "neon: {} functions, {} calls agree in {} builds",
        names.len(),
        calls.len(),
        objects.len()
    );
}

/// What hod does not lower is refused by name, each case by itself.
#[test]
fn what_is_not_lowered_is_refused_by_name() {
    let cases: Vec<(String, &'static str)> = vec![
        // A shift amount that is not a constant.
        (
            "declare <4 x i32> @llvm.aarch64.neon.vsli.v4i32(<4 x i32>, <4 x i32>, i32)\n\
             define <4 x i32> @f(<4 x i32> %a, <4 x i32> %b, i32 %n) {\n  \
             %r = call <4 x i32> @llvm.aarch64.neon.vsli.v4i32(<4 x i32> %a, <4 x i32> %b, i32 %n)\n  \
             ret <4 x i32> %r\n}\n"
                .to_owned(),
            "a64:intrinsic-immediate",
        ),
        // A shift amount out of range.
        (
            "declare <8 x i8> @llvm.aarch64.neon.rshrn.v8i8(<8 x i16>, i32)\n\
             define <8 x i8> @f(<8 x i16> %a) {\n  \
             %r = call <8 x i8> @llvm.aarch64.neon.rshrn.v8i8(<8 x i16> %a, i32 9)\n  \
             ret <8 x i8> %r\n}\n"
                .to_owned(),
            "a64:intrinsic-immediate",
        ),
        // A lane out of range.
        (
            "declare <4 x i16> @llvm.aarch64.neon.sqdmulh.lane.v4i16.v4i16(<4 x i16>, <4 x i16>, i32)\n\
             define <4 x i16> @f(<4 x i16> %a, <4 x i16> %b) {\n  \
             %r = call <4 x i16> @llvm.aarch64.neon.sqdmulh.lane.v4i16.v4i16(<4 x i16> %a, <4 x i16> %b, i32 4)\n  \
             ret <4 x i16> %r\n}\n"
                .to_owned(),
            "a64:intrinsic-immediate",
        ),
        // A barrier option that is not one.
        (
            "declare void @llvm.aarch64.dmb(i32)\n\
             define void @f() {\n  call void @llvm.aarch64.dmb(i32 4)\n  ret void\n}\n"
                .to_owned(),
            "a64:intrinsic-immediate",
        ),
        (
            "declare void @llvm.aarch64.isb(i32)\n\
             define void @f() {\n  call void @llvm.aarch64.isb(i32 0)\n  ret void\n}\n"
                .to_owned(),
            "a64:intrinsic-immediate",
        ),
        // A vector shape no instruction takes.
        (
            "declare <2 x i64> @llvm.aarch64.neon.smax.v2i64(<2 x i64>, <2 x i64>)\n\
             define <2 x i64> @f(<2 x i64> %a, <2 x i64> %b) {\n  \
             %r = call <2 x i64> @llvm.aarch64.neon.smax.v2i64(<2 x i64> %a, <2 x i64> %b)\n  \
             ret <2 x i64> %r\n}\n"
                .to_owned(),
            "a64:intrinsic-target",
        ),
        (
            "declare <4 x float> @llvm.aarch64.neon.frint32x.v4f32(<4 x float>)\n\
             declare <4 x half> @llvm.aarch64.neon.frint32x.v4f16(<4 x half>)\n\
             define <4 x half> @f(<4 x half> %a) {\n  \
             %r = call <4 x half> @llvm.aarch64.neon.frint32x.v4f16(<4 x half> %a)\n  \
             ret <4 x half> %r\n}\n"
                .to_owned(),
            "a64:intrinsic-target",
        ),
    ];
    let cases: Vec<(&str, &'static str)> = cases.iter().map(|(t, r)| (t.as_str(), *r)).collect();
    assert_refused(&cases);
}

/// The bfloat intrinsics compile since WP-101 (`tests/tail3.rs` checks
/// them against `llc`).
#[test]
fn bfloat_intrinsics_compile() {
    let text = "declare <4 x float> @llvm.aarch64.neon.bfdot.v4f32.v8bf16(<4 x float>, <8 x bfloat>, <8 x bfloat>)\n\
                define <4 x float> @f(<4 x float> %a, <8 x bfloat> %b, <8 x bfloat> %c) {\n  \
                %r = call <4 x float> @llvm.aarch64.neon.bfdot.v4f32.v8bf16(<4 x float> %a, <8 x bfloat> %b, <8 x bfloat> %c)\n  \
                ret <4 x float> %r\n}\n";
    assert!(compile_ll(text).is_ok());
}
